CREATE TABLE tt_financial_actions(id TEXT PRIMARY KEY,tenancy_id TEXT NOT NULL REFERENCES tt_tenancies(id),kind TEXT NOT NULL CHECK(kind IN ('refund','credit','write_off')),version INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','approved','recorded')),prepared_by TEXT NOT NULL,revised_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE tt_financial_revisions(action_id TEXT NOT NULL REFERENCES tt_financial_actions(id),version INTEGER NOT NULL,payload TEXT NOT NULL,source_snapshot TEXT NOT NULL,fingerprint TEXT NOT NULL,prepared_by TEXT NOT NULL,prepared_at TEXT NOT NULL,PRIMARY KEY(action_id,version));
CREATE TABLE tt_financial_approvals(action_id TEXT NOT NULL,version INTEGER NOT NULL,fingerprint TEXT NOT NULL,approved_by TEXT NOT NULL,approved_at TEXT NOT NULL,approval_label TEXT,PRIMARY KEY(action_id,version),FOREIGN KEY(action_id,version) REFERENCES tt_financial_revisions(action_id,version));
CREATE TABLE tt_financial_recordings(id TEXT PRIMARY KEY,action_id TEXT NOT NULL UNIQUE REFERENCES tt_financial_actions(id),version INTEGER NOT NULL,receipt_id TEXT REFERENCES tt_receipts(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),on_day TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TABLE tt_refund_checks(action_id TEXT NOT NULL REFERENCES tt_financial_actions(id),version INTEGER NOT NULL,number TEXT NOT NULL UNIQUE,state TEXT NOT NULL CHECK(state IN ('draft','recorded_external')),snapshot TEXT NOT NULL,prepared_by TEXT NOT NULL,prepared_at TEXT NOT NULL,PRIMARY KEY(action_id,version));
INSERT INTO tt_role_actions(role,action) VALUES ('portfolio_manager','finance.prepare'),('portfolio_manager','finance.revise'),('portfolio_manager','finance.approve'),('portfolio_manager','finance.record'),('portfolio_manager','finance.check');
DROP VIEW tt_net_receipts;
CREATE VIEW tt_net_receipts AS SELECT r.*,NULL AS reversal_of FROM tt_receipts r
 UNION ALL SELECT x.id,r.charge_id,-r.amount_cents,x.day,x.reference,x.recorded_at,r.currency,r.method,r.id FROM tt_receipt_reversals x JOIN tt_receipts r ON r.id=x.receipt_id
 UNION ALL SELECT x.id,r.charge_id,-x.amount_cents,x.on_day,x.reference,x.recorded_at,r.currency,r.method,r.id FROM tt_financial_recordings x JOIN tt_receipts r ON r.id=x.receipt_id;
-- Partial refunds follow the original receipt's frozen owner allocation, never the property's new owners.
CREATE VIEW tt_refund_owner_weights AS SELECT x.id AS recording_id,r.id AS receipt_id,r.amount_cents AS receipt_cents,x.amount_cents,x.on_day,x.reference,x.recorded_by,x.recorded_at,j.property_id,j.owner_key,j.tenancy_id,j.fund,SUM(l.debit_cents) AS weight FROM tt_financial_recordings x JOIN tt_receipts r ON r.id=x.receipt_id JOIN tt_journal j ON j.source_kind='receipt' AND j.source_id=r.id JOIN tt_journal_lines l ON l.id=j.id AND l.account='cash' GROUP BY x.id,j.owner_key;
CREATE VIEW tt_refund_owner_allocations AS SELECT w.*,CAST(amount_cents*weight/receipt_cents AS INTEGER)+CASE WHEN owner_key=(SELECT owner_key FROM tt_refund_owner_weights z WHERE z.recording_id=w.recording_id ORDER BY weight DESC,owner_key LIMIT 1) THEN amount_cents-(SELECT SUM(CAST(amount_cents*weight/receipt_cents AS INTEGER)) FROM tt_refund_owner_weights z WHERE z.recording_id=w.recording_id) ELSE 0 END AS allocated FROM tt_refund_owner_weights w;
CREATE TRIGGER tt_refund_journal AFTER INSERT ON tt_financial_recordings WHEN NEW.receipt_id IS NOT NULL BEGIN
 INSERT INTO tt_journal(id,day,property_id,owner_key,tenancy_id,fund,source_kind,source_id,reference,lines,recorded_by,recorded_at)
 SELECT recording_id||':'||owner_key,on_day,property_id,owner_key,tenancy_id,fund,'refund',recording_id,reference,json_array(json_object('account','receivable','debit',allocated,'credit',0),json_object('account','cash','debit',0,'credit',allocated)),recorded_by,recorded_at FROM tt_refund_owner_allocations WHERE recording_id=NEW.id AND allocated>0;
END;
-- Every old receipt/reduction door respects reservations, including concessions and close corrections.
CREATE TRIGGER tt_reserved_receipt BEFORE INSERT ON tt_receipts WHEN NEW.amount_cents>(SELECT q.amount_cents-COALESCE((SELECT SUM(amount_cents) FROM tt_net_receipts WHERE charge_id=q.id),0)-COALESCE((SELECT SUM(amount_cents) FROM tt_adjustments WHERE charge_id=q.id),0)-COALESCE((SELECT amount_cents FROM tt_payment_reserved WHERE charge_id=q.id),0) FROM tt_charges q WHERE q.id=NEW.charge_id) BEGIN SELECT RAISE(ABORT,'reserved_payment_balance'); END;
CREATE TRIGGER tt_reserved_adjustment BEFORE INSERT ON tt_adjustments WHEN NEW.amount_cents>(SELECT q.amount_cents-COALESCE((SELECT SUM(amount_cents) FROM tt_net_receipts WHERE charge_id=q.id),0)-COALESCE((SELECT SUM(amount_cents) FROM tt_adjustments WHERE charge_id=q.id),0)-COALESCE((SELECT amount_cents FROM tt_payment_reserved WHERE charge_id=q.id),0) FROM tt_charges q WHERE q.id=NEW.charge_id) BEGIN SELECT RAISE(ABORT,'reserved_payment_balance'); END;
CREATE TRIGGER tt_refund_limit BEFORE INSERT ON tt_financial_recordings WHEN NEW.receipt_id IS NOT NULL AND (EXISTS(SELECT 1 FROM tt_receipt_reversals WHERE receipt_id=NEW.receipt_id) OR NEW.amount_cents>(SELECT amount_cents FROM tt_receipts WHERE id=NEW.receipt_id)-COALESCE((SELECT SUM(amount_cents) FROM tt_financial_recordings WHERE receipt_id=NEW.receipt_id),0)) BEGIN SELECT RAISE(ABORT,'refund_limit'); END;
CREATE TRIGGER tt_reverse_refunded BEFORE INSERT ON tt_receipt_reversals WHEN EXISTS(SELECT 1 FROM tt_financial_recordings WHERE receipt_id=NEW.receipt_id) BEGIN SELECT RAISE(ABORT,'refund_limit'); END;
